;; d0 = Time_ToTicks(a0 = time) : {h,m,s,1/200} -> number of 1/200 s ticks.
Time_ToTicks:
	ifd	OPT_TIME
	; OPT_TIME: duration {h,m,s,1/200} -> ticks of 1/200 s, without calling _lmul
	; h*720000 = (h*11250)<<6 ; identical result (checked by tools/difftest.py)
	moveq	#0,d0
	move.b	(a0),d0
	mulu.w	#11250,d0
	lsl.l	#$6,d0
	moveq	#0,d1
	move.b	$1(a0),d1
	mulu.w	#12000,d1
	add.l	d1,d0
	moveq	#0,d1
	move.b	$2(a0),d1
	mulu.w	#200,d1
	add.l	d1,d0
	moveq	#0,d1
	move.b	$3(a0),d1
	add.l	d1,d0
	rts
	else
	move.l	d3,-(a7)
	move.l	a2,-(a7)
	movea.l	a0,a2
	moveq	#0,d3
	move.b	$3(a2),d3
	moveq	#0,d1
	move.b	$2(a2),d1
	move.l	d1,d0
	add.l	d0,d0
	add.l	d1,d0
	lsl.l	#$3,d0
	add.l	d1,d0
	lsl.l	#$3,d0
	add.l	d0,d3
	moveq	#0,d0
	move.b	$1(a2),d0
	move.l	d0,d2
	add.l	d2,d2
	add.l	d0,d2
	lsl.l	#$4,d2
	sub.l	d0,d2
	lsl.l	#$3,d2
	sub.l	d0,d2
	lsl.l	#$5,d2
	add.l	d2,d3
	moveq	#0,d0
	move.b	(a0),d0
	move.l	#$afc80,d1
	jsr	(PureC_LongMul).l
	add.l	d0,d3
	move.l	d3,d0
	movea.l	(a7)+,a2
	move.l	(a7)+,d3
	rts

	endif

;; Time_FromTicks(d0 = ticks, a0 = out) : ticks -> {h,m,s,1/200}.
Time_FromTicks:
	ifd	OPT_TIME
	; OPT_TIME: ticks -> {h,m,s,1/200} without _uldiv/_lmul (unsigned division)
	; x/720000 = (x>>6)/11250 exactly ; remainder = (remainder<<6)|(x&63)
	move.l	d0,d1
	lsr.l	#$6,d1
	divu.w	#11250,d1		; quotient < 5966: no overflow
	move.b	d1,(a0)
	moveq	#63,d2
	and.l	d0,d2
	clr.w	d1
	swap	d1
	lsl.l	#$6,d1
	or.l	d2,d1			; remainder < 720000
	divu.w	#12000,d1		; minutes < 60
	move.b	d1,$1(a0)
	clr.w	d1
	swap	d1			; remainder < 12000
	divu.w	#200,d1			; seconds < 60
	move.b	d1,$2(a0)
	moveq	#0,d0
	move.w	d1,d0			; d0 = seconds, as in the original
	swap	d1
	move.b	d1,$3(a0)
	rts
	else
	movem.l	d3-d4/a2,-(a7)
	movea.l	a0,a2
	move.l	d0,d3
	move.l	#$afc80,d1
	jsr	(PureC_LongDivU).l
	move.l	d0,d4
	move.b	d4,(a2)
	move.l	d4,d0
	move.l	#$afc80,d1
	jsr	(PureC_LongMul).l
	sub.l	d0,d3
	move.l	d3,d0
	move.l	#$2ee0,d1
	jsr	(PureC_LongDivU).l
	move.l	d0,d4
	move.b	d4,$1(a2)
	move.l	d4,d1
	add.l	d1,d1
	add.l	d4,d1
	lsl.l	#$4,d1
	sub.l	d4,d1
	lsl.l	#$3,d1
	sub.l	d4,d1
	lsl.l	#$5,d1
	sub.l	d1,d3
	move.l	d3,d0
	move.l	#$c8,d1
	jsr	(PureC_LongDivU).l
	move.l	d0,d4
	move.b	d4,$2(a2)
	move.l	d4,d1
	add.l	d1,d1
	add.l	d4,d1
	lsl.l	#$3,d1
	add.l	d4,d1
	lsl.l	#$3,d1
	sub.l	d1,d3
	move.b	d3,$3(a2)
	movem.l	(a7)+,d3-d4/a2
	rts
	endif

;; Time_Add(a0 = a, a1 = b, stack = out) : out = a + b  (all in {h,m,s,1/200}).
Time_Add:
	movem.l	d3-d4/a3,-(a7)
	movea.l	a1,a3
	bsr.w	Time_ToTicks
	move.l	d0,d3
	movea.l	a3,a0
	bsr.w	Time_ToTicks
	move.l	d0,d4
	move.l	d3,d0
	add.l	d4,d0
	movea.l	$10(a7),a0
	bsr.w	Time_FromTicks
	movem.l	(a7)+,d3-d4/a3
	rts

;; Time_Sub(a0 = a, a1 = b, stack = out) : out = a - b.
Time_Sub:
	movem.l	d3-d4/a3,-(a7)
	movea.l	a1,a3
