	move.l	d0,d3
	movea.l	a3,a0
	bsr.w	Time_ToTicks
	move.l	d0,d4
	move.l	d3,d0
	sub.l	d4,d0
	movea.l	$10(a7),a0
	bsr.w	Time_FromTicks
	movem.l	(a7)+,d3-d4/a3
	rts

