;; Cell_SetArrow(a0 = board cell, d0 = direction 0-3, d1 = owner player 0-3) :
;; sets the cell type to $40 (arrow) in byte 0 bits 4-6, the direction in byte 1
;; bits 0-1 and the owner in byte 1 bits 2-3. Used by Arrow_Create.
Cell_SetArrow:
	andi.b	#$8f,(a0)
	ori.b	#$40,(a0)
	andi.b	#$fc,$1(a0)
	moveq	#3,d2
	and.b	d0,d2
	or.b	d2,$1(a0)
	andi.b	#$f3,$1(a0)
	move.b	d1,d0
	lsl.b	#$2,d0
	and.b	#$c,d0
	or.b	d0,$1(a0)
	rts

;; Cell_ClearType(a0 = board cell) : type bits 4-6 = 0 (empty tile, walls kept).
Cell_ClearType:
	andi.b	#$8f,(a0)
	rts

;; Cell_SetRocket(a0 = board cell, d0 = owner player 0-3) : sets the cell type to
;; $20 (rocket) and the owner in byte 1 bits 2-3. Used when rockets move (Everybody Move).
Cell_SetRocket:
	andi.b	#$8f,(a0)
	ori.b	#$20,(a0)
	andi.b	#$f3,$1(a0)
	move.b	d0,d1
	lsl.b	#$2,d1
	and.b	#$c,d1
	or.b	d1,$1(a0)
	rts

;; Cell_ClearRocket(a0 = board cell) : clears the cell type bits (same code
;; as Cell_ClearType); used by Spinner_EverybodyMove to lift a rocket off its old cell.
Cell_ClearRocket:
	andi.b	#$8f,(a0)
	rts

