;; Moves one creature (mouse or cat) by d0 (16.16 fixed point, in tiles).
;; in: a0 = creature, d0 = distance for this frame.
;; Creature record (26 bytes):
;;   +$00.l x   (high word = column 0-11, low word $8000 = tile centre)
;;   +$04.l y   (high word = row 0-8)
;;   +$08.l animation counter
;;   +$10.w direction (0 left, 1 right, 2 down, 3 up)
;;   +$12.w kind (1 mouse, 2 gold mouse, 3 purple mouse, 4 cat)
;;   +$14.w state (0 free slot, 1 walking, 2 falling into a hole,
;;          3 caught / flying, 5 entering a rocket)
;;   +$16.w "state just changed" flag
;; Algorithm:
;;   if the current tile is a rocket: state = 5, Rocket_Enter()
;;   if the current tile is a hole:   state = 2 (falls)
;;   while distance left:
;;     advance along the direction; the board wraps around (12 x 9)
;;     when crossing the centre of a tile:
;;       index = (arrow ? arrow direction : direction) * 16 + walls
;;       new direction = gTurnTable[index]   ("turn right at walls")
;;       a cat meeting an arrow that points against it damages the
;;       arrow (Arrow_HitByCat)
;;       on a turn: snap to the centre, keep the remaining distance
Creature_Move:
	movem.l	d3-d7/a2-a4,-(a7)
	subq.w	#$6,a7
	movea.l	a0,a2
	move.l	d0,d6
	cmpi.w	#$2,$14(a2)
	beq.s	L_066ac
	cmpi.w	#$3,$14(a2)
	bne.s	L_066b4
L_066ac:
	clr.w	$16(a2)
	bra.w	L_069d2
L_066b4:
	move.w	$12(a2),d0
	beq.w	L_069d2
	move.w	(a2),d1
	move.w	$4(a2),d0
	jsr	(Level_GetCell).l
	move.b	(a0),d3
	move.b	$1(a0),d0
	moveq	#15,d4
	and.b	d3,d4
	and.b	#$70,d3
	moveq	#3,d5
