;; in: d0 = row (0-8), d1 = column (0-11). out: a0 = cell (2 bytes)
;; in the current level map: map + $22 + row*24 + column*2.
;; Cell byte 0: bits 0-3 = walls, bits 4-6 = type
;;   ($00 empty, $10 spawner, $20 rocket, $30 hole, $40 arrow).
;; Cell byte 1: bits 0-1 = arrow direction (0 left, 1 right, 2 down, 3 up).
Level_GetCell:
	move.w	d4,-(a7)
	move.w	d0,d4
	moveq	#0,d2
	move.w	d1,d2
	add.l	d2,d2
	moveq	#0,d1
	move.w	d4,d1
	move.l	d1,d0
	add.l	d0,d0
	add.l	d1,d0
	lsl.l	#$3,d0
	movea.l	(gLevelMap).l,a0
	adda.l	d0,a0
	lea.l	$22(a0,d2.l),a0
	move.w	(a7)+,d4
	rts

;; a0 = Level_GetHeader() : address of the current level (34-byte header,
;; then the 9 x 12 tiles).
Level_GetHeader:
