;; Game_Init() : start-up of the system layer: machine detection (System_Init),
;; VBL, video, keyboard, audio, graphics, data cache off, and opens CHUCHU.LNK.
Game_Init:
	jsr	(System_Init).l
	jsr	(Vbl_Init).l
	jsr	(Video_Init).l
	jsr	(Ikbd_Init).l
	jsr	(Audio_Init).l	; resvalid
	jsr	(Screen_GfxInit).l
	jsr	(System_DataCacheDisable).l
	lea.l	(LinkFileName).l,a0
	jsr	(File_LinkInit).l
	move.l	a0,(gLinkFile).l
	rts

;; Game_Exit() : undoes Game_Init in reverse order and gives the machine back to
;; GEM (with FIX_MOUSE the mouse is switched back on first).
Game_Exit:
	jsr	(Screen_GfxDeInit).l
	ifd	FIX_MOUSE
	; FIX_MOUSE: when no player used the mouse, Controls_ApplyIkbdMode sent
	; $12 (mouse off) + $14 to the IKBD, and the original game never turned
	; it back on: dead mouse under GEM. Send $08 (relative mouse mode)
	; before handing the ACIA vector back to the system.
	jsr	(Ikbd_MouseMode).l
	endif
	jsr	(Ikbd_DeInit).l
	jsr	(Video_DeInit).l
	jsr	(Vbl_DeInit).l
	jsr	(System_DeInit).l
	jsr	(Audio_DeInit).l
	jsr	(Vbl_Wait).l
	jsr	(Ikbd_FlushGemdos).l
	jsr	(Audio_SoundChipOff).l
	movea.l	(gLinkFile).l,a0
	jsr	(File_LinkDeInit).l
	rts

