;; Sound_Init() : loads the music player and tunes (Music_LoadPlayer) and the
;; sound effect samples (Sfx_LoadSamples). Called once at boot.
Sound_Init:
	jsr	(Music_LoadPlayer).l
	jsr	(Sfx_LoadSamples).l
	rts

;; Sound_DeInit() : frees the music (Music_Free), the DMA sound buffers
;; (Sfx_DeInit) and silences the sound chip.
Sound_DeInit:
	jsr	(Music_Free).l
	jsr	(Sfx_DeInit).l
	jsr	(Audio_SoundChipOff).l
	rts

;; Sound_Update() : once per frame: music (Music_Update) and sound effects (Sfx_Update).
Sound_Update:
	jsr	(Music_Update).l
	jsr	(Sfx_Update).l
	rts

