; ---------------------------------------------------------------------------
; OPT_BLIT: restore the board background with the blitter (STE, Mega STE,
; TT, Falcon). A tile = 16 lines x 8 bytes (4 planes), line pitch 160, tile
; row pitch $a00. Consecutive dirty tiles of a row are copied in ONE blitter
; operation (HOP=source, OP=S, masks $ffff, skew 0).
; Started in shared mode + bset #7 restart loop (like the game's sprites):
; interrupts (music) are not blocked.
; The blitter registers we change are saved and restored.
; ---------------------------------------------------------------------------

;; Blit_RestoreCells: a0 = dirty masks of the 9 rows, a1 = source (column 1),
;; 4(sp) = destination. Bits 1-12 = columns, cleared after the copy.
Blit_RestoreCells:
	movem.l	d0-d7/a0-a6,-(a7)
	movea.l	$40(a7),a2
	bsr.w	Blit_Begin
	moveq	#8,d0
.row:
	move.w	(a0)+,d2
	lsr.w	#$1,d2
	andi.w	#$0fff,d2		; 12 columns (bits 0-11 after the shift)
	beq.s	.next
	bsr.w	Blit_Row
.next:
	andi.w	#$e001,-$2(a0)
	lea.l	$a00(a1),a1
	lea.l	$a00(a2),a2
	dbra	d0,.row
	bsr.w	Blit_End
	movem.l	(a7)+,d0-d7/a0-a6
	rts

;; Blit_RestoreBorder: board borders. 9 rows: bit 0 = column 0, bit 13 = column 13
;; (cleared), then a 10th row of 14 tiles (bits 0-13, not cleared, as in
;; the original).
Blit_RestoreBorder:
	movem.l	d0-d7/a0-a6,-(a7)
	movea.l	$40(a7),a2
	bsr.w	Blit_Begin
	moveq	#8,d0
.row:
	move.w	(a0)+,d2
	andi.w	#$2001,d2		; bits 0 and 13 only: 2 separate tiles
	beq.s	.next
	bsr.w	Blit_Row
.next:
	andi.w	#$1ffe,-$2(a0)
	lea.l	$a00(a1),a1
	lea.l	$a00(a2),a2
	dbra	d0,.row
	move.w	(a0)+,d2
	beq.s	.done
	andi.w	#$3fff,d2		; 14 tiles
	beq.s	.done
	bsr.w	Blit_Row
.done:
	bsr.w	Blit_End
	movem.l	(a7)+,d0-d7/a0-a6
	rts

;; Blit_Row: d2 = dirty tile bits (bits beyond the row already 0),
;; a1/a2 = start of the source/destination row, a6 = $ffff8a00.
;; Walks the bits by shifting: skips zeros, measures each run of ones and
;; starts one copy per run; returns as soon as the mask is empty.
Blit_Row:
	moveq	#-1,d1			; current column
.seek:
	tst.w	d2
	beq.s	.out
.zero:
	addq.w	#$1,d1
	lsr.w	#$1,d2
	bcc.s	.zero
	move.w	d1,d5			; start of a run
.one:
	addq.w	#$1,d1
	lsr.w	#$1,d2
	bcs.s	.one
	move.w	d1,d6
	sub.w	d5,d6			; length of the run
	bsr.s	Blit_Run
	bra.s	.seek
.out:
	rts

;; Blit_Run: copy d6 tiles starting at column d5.
Blit_Run:
	move.w	d5,d7
	lsl.w	#$3,d7
	lea.l	(a1,d7.w),a3
	move.l	a3,$24(a6)		; source
	lea.l	(a2,d7.w),a3
	move.l	a3,$32(a6)		; destination
	move.w	d6,d7
	lsl.w	#$2,d7
	move.w	d7,$36(a6)		; X count = 4 words per tile
	move.w	d6,d7
	lsl.w	#$3,d7
	move.w	#162,d4
	sub.w	d7,d4			; Y inc = 160 - (8n - 2)
	move.w	d4,$22(a6)
	move.w	d4,$30(a6)
	move.w	#16,$38(a6)		; Y count = 16 lines
	ifd	BLIT_CHECK
	addq.l	#$1,(Opt_BlitRuns).l
	endif
	move.b	#$80,$3c(a6)		; start, shared (non-HOG) mode
.wait:
	bset.b	#$7,$3c(a6)		; restart while the blitter is busy
	nop
	bne.s	.wait
	ifd	BLIT_CHECK
	; check: destination == source, byte for byte
	movem.l	d0-d1/a3-a4,-(a7)
	move.w	d5,d0
	lsl.w	#$3,d0
	lea.l	(a1,d0.w),a3
	lea.l	(a2,d0.w),a4
	moveq	#15,d0
.cl:	move.w	d6,d1
	add.w	d1,d1
	subq.w	#$1,d1
.cw:	cmpm.l	(a3)+,(a4)+
	beq.s	.ok
	addq.l	#$1,(Opt_BlitErrors).l
.ok:	dbra	d1,.cw
	move.w	d6,d1
	lsl.w	#$3,d1
	suba.w	d1,a3
	suba.w	d1,a4
	lea.l	160(a3),a3
	lea.l	160(a4),a4
	dbra	d0,.cl
	movem.l	(a7)+,d0-d1/a3-a4
	endif
	rts

;; Blit_Begin: wait for the blitter, save its registers, set the constant ones.
Blit_Begin:
	movea.w	#$8a00,a6
.idle:
	btst.b	#$7,$3c(a6)
	nop
	bne.s	.idle
	lea.l	(Opt_BlitSave).l,a3
	move.w	$20(a6),(a3)+
	move.w	$22(a6),(a3)+
	move.w	$28(a6),(a3)+
	move.w	$2a(a6),(a3)+
	move.w	$2c(a6),(a3)+
	move.w	$2e(a6),(a3)+
	move.w	$30(a6),(a3)+
	move.w	$36(a6),(a3)+
	move.b	$3a(a6),(a3)+
	move.b	$3b(a6),(a3)+
	move.b	$3d(a6),(a3)+
	move.w	#2,$20(a6)		; src X inc
	move.w	#2,$2e(a6)		; dst X inc
	moveq	#-1,d7
	move.w	d7,$28(a6)		; end masks
	move.w	d7,$2a(a6)
	move.w	d7,$2c(a6)
	move.b	#$2,$3a(a6)		; HOP = source
	move.b	#$3,$3b(a6)		; OP = source
	clr.b	$3d(a6)			; skew 0, no FXSR/NFSR
	rts

;; Blit_End: restore the blitter registers.
Blit_End:
	lea.l	(Opt_BlitSave).l,a3
	move.w	(a3)+,$20(a6)
	move.w	(a3)+,$22(a6)
	move.w	(a3)+,$28(a6)
	move.w	(a3)+,$2a(a6)
	move.w	(a3)+,$2c(a6)
	move.w	(a3)+,$2e(a6)
	move.w	(a3)+,$30(a6)
	move.w	(a3)+,$36(a6)
	move.b	(a3)+,$3a(a6)
	move.b	(a3)+,$3b(a6)
	move.b	(a3)+,$3d(a6)
	rts
	endif

