;; Level bank:
;;   +$0000  10 pointers to the loaded .CHU files (index = level set)
;;   +$0028  wall masks [10 sets][25 levels][38 bytes] (Level_BuildWallMask)
;;   +$2544  gLevelSet, +$2546 gLevelIndex
;;   +$254a  10 longs cleared at load time
;;   +$2572  25 words set to 40 at load time
;;
;; .CHU file = "CHUL" + long level count + 25 levels of 250 bytes.
;; Level (250 bytes) = 34-byte header + 9 rows x 12 columns x 2 bytes.
;;   header +$08 title (C string), +$1d objective (0 puzzle, 1 battle,
;;   2 get mice, 3 feed cat, 4 100 mice, 5 cat soccer, 6 win 100),
;;   +$1e..+$21 arrows in stock for puzzles (one byte per direction)
;;   cell byte 0 : bits 0-3 walls (1 left, 2 right, 4 down, 8 up)
;;                 bits 4-6 type ($10 spawner, $20 rocket, $30 hole, $40 arrow)
;;   cell byte 1 : bits 0-1 direction (0 left, 1 right, 2 down, 3 up)
;; The board wraps around: leaving on one side enters on the other.
gLevelBank:
	ds.b	40
gLevelWallMasks:
	ds.b	9500
gLevelSet:
	ds.b	2
gLevelIndex:
